(()=>{'use strict';const $=id=>document.getElementById(id);const fmt=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.max(0,n%60).toString().padStart(2,'0')}`;let saved={};try{saved=JSON.parse(localStorage.getItem('tb-space-v1')||'{}')||{}}catch{}const persist=()=>{try{localStorage.setItem('tb-space-v1',JSON.stringify(saved))}catch{}};const counters=()=>{$('session-count').textContent=saved.sessions?`${saved.sessions} pausa${saved.sessions===1?'':'s'} completada${saved.sessions===1?'':'s'} en este navegador.`:'Tus pausas completadas aparecerán aquí.'};function completed(){saved.sessions=(saved.sessions||0)+1;persist();counters()}counters();
function tab(name){document.querySelectorAll('[data-tool]').forEach(b=>{const active=b.dataset.tool===name;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1;$(b.dataset.tool+'-panel').hidden=!active})}document.querySelectorAll('[data-tool]').forEach((b,i,arr)=>{b.onclick=()=>tab(b.dataset.tool);b.onkeydown=e=>{let j;if(e.key==='ArrowRight')j=(i+1)%arr.length;if(e.key==='ArrowLeft')j=(i+arr.length-1)%arr.length;if(e.key==='Home')j=0;if(e.key==='End')j=arr.length-1;if(j!==undefined){e.preventDefault();tab(arr[j].dataset.tool);arr[j].focus()}}});
function openLinkedTool(){const match=location.hash.match(/^#(breath|sound|focus|observe)-tab$/);if(match){tab(match[1]);$('explorar').scrollIntoView();}}window.addEventListener('hashchange',openLinkedTool);openLinkedTool();
let bt=null,bElapsed=0,bStart=0,bTotal=60;function breathFrame(){const elapsed=bElapsed+(Date.now()-bStart)/1000;const left=Math.max(0,Math.ceil(bTotal-elapsed));$('breath-time').textContent=fmt(left);if(elapsed>=bTotal){clearInterval(bt);bt=null;bElapsed=0;$('breath-circle').classList.remove('grow');$('breath-prompt').textContent='Vuelve a tu ritmo.';$('breath-start').textContent='Repetir';$('breath-rhythm').disabled=false;$('breath-length').disabled=false;completed();return}const [inside,outside]=$('breath-rhythm').value.split(',').map(Number);const inhale=elapsed%(inside+outside)<inside;const circle=$('breath-circle');circle.style.transitionDuration=(inhale?inside:outside)+'s';circle.classList.toggle('grow',inhale);$('breath-prompt').textContent=inhale?'Inspira suavemente':'Suelta el aire'}$('breath-start').onclick=()=>{if(bt){bElapsed+=(Date.now()-bStart)/1000;clearInterval(bt);bt=null;$('breath-start').textContent='Continuar';$('breath-prompt').textContent='En pausa.';return}bTotal=Number($('breath-length').value);bStart=Date.now();$('breath-start').textContent='Pausar';$('breath-rhythm').disabled=true;$('breath-length').disabled=true;breathFrame();bt=setInterval(breathFrame,150)};function resetBreath(){clearInterval(bt);bt=null;bElapsed=0;$('breath-start').textContent='Empezar';$('breath-prompt').textContent='Cuando quieras.';$('breath-circle').classList.remove('grow');$('breath-rhythm').disabled=false;$('breath-length').disabled=false;$('breath-time').textContent=fmt(Number($('breath-length').value))}$('breath-reset').onclick=resetBreath;$('breath-length').onchange=resetBreath;
let audio=null,master=null,nodes=[],soundOn=false,soundBusy=false;const sliders=['wind','rain','deep','master'];for(const id of sliders){if(Number.isFinite(saved[id]))$(id).value=saved[id];$(id).oninput=()=>{saved[id]=Number($(id).value);$(id).nextElementSibling.textContent=$(id).value+' %';persist();updateMix()};$(id).nextElementSibling.textContent=$(id).value+' %'}function updateMix(){if(!audio)return;master.gain.setTargetAtTime(Number($('master').value)/100*.5,audio.currentTime,.1);nodes.forEach((n,i)=>n.gain.gain.setTargetAtTime(Number($(sliders[i]).value)/100*.5,audio.currentTime,.1))}async function playSound(){if(soundBusy||soundOn)return;soundBusy=true;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('unavailable');audio=new AC();await audio.resume();master=audio.createGain();master.gain.value=0;master.connect(audio.destination);const buffer=audio.createBuffer(1,audio.sampleRate*7,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;nodes=[['lowpass',650],['highpass',1400],['lowpass',160]].map(([type,hz])=>{const source=audio.createBufferSource();source.buffer=buffer;source.loop=true;const filter=audio.createBiquadFilter();filter.type=type;filter.frequency.value=hz;filter.Q.value=.4;const gain=audio.createGain();gain.gain.value=0;source.connect(filter);filter.connect(gain);gain.connect(master);source.start(0,Math.random()*5);return{source,gain}});soundOn=true;updateMix();$('sound-state').textContent='Tu mezcla está sonando.';$('sound-start').textContent='Reproduciendo';$('sound-start').disabled=true;$('sound-dock').hidden=false}catch{await stopSound();$('sound-state').textContent='No se pudo iniciar el audio. Prueba a pulsar Reproducir de nuevo.'}finally{soundBusy=false}}async function stopSound(){soundOn=false;nodes.forEach(n=>{try{n.source.stop()}catch{}});nodes=[];if(audio){try{await audio.close()}catch{}}audio=null;master=null;$('sound-state').textContent='Sonido apagado.';$('sound-start').textContent='Reproducir';$('sound-start').disabled=false;$('sound-dock').hidden=true}$('sound-start').onclick=playSound;$('sound-stop').onclick=stopSound;$('dock-stop').onclick=stopSound;$('dock-open').onclick=()=>{tab('sound');$('explorar').scrollIntoView({behavior:'smooth'})};document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{b.dataset.preset.split(',').forEach((v,i)=>{$(sliders[i]).value=v;$(sliders[i]).dispatchEvent(new Event('input'))});$('sound-state').textContent=soundOn?'Nuevo ambiente aplicado.':'Ambiente preparado. Pulsa Reproducir.'});
let ft=null,focusSeconds=1500,focusRemaining=1500,focusEnd=0;const intent=$('focus-intent');intent.value=typeof saved.intent==='string'?saved.intent:'';intent.oninput=()=>{saved.intent=intent.value;persist()};function focusFrame(){focusRemaining=Math.max(0,Math.ceil((focusEnd-Date.now())/1000));$('focus-clock').textContent=fmt(focusRemaining);if(focusRemaining===0){clearInterval(ft);ft=null;$('focus-start').textContent='Repetir';$('focus-state').textContent='Tiempo completado. Haz una pausa.';completed();if($('focus-chime').checked)chime()}}async function chime(){try{const AC=window.AudioContext||window.webkitAudioContext;const a=new AC();await a.resume();const o=a.createOscillator(),g=a.createGain();o.frequency.value=523.25;g.gain.setValueAtTime(0,a.currentTime);g.gain.linearRampToValueAtTime(.07,a.currentTime+.05);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+1.3);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+1.4);o.onended=()=>a.close()}catch{}}$('focus-start').onclick=()=>{if(ft){focusFrame();clearInterval(ft);ft=null;$('focus-start').textContent='Continuar';$('focus-state').textContent='En pausa.';return}if(!focusRemaining)focusRemaining=focusSeconds;focusEnd=Date.now()+focusRemaining*1000;$('focus-start').textContent='Pausar';$('focus-state').textContent=intent.value.trim()||'Una cosa cada vez.';ft=setInterval(focusFrame,200);focusFrame()};function focusReset(){clearInterval(ft);ft=null;focusRemaining=focusSeconds;$('focus-clock').textContent=fmt(focusRemaining);$('focus-start').textContent='Empezar';$('focus-state').textContent='Este rato es tuyo.'}$('focus-reset').onclick=focusReset;document.querySelectorAll('[data-minutes]').forEach(b=>b.onclick=()=>{focusSeconds=Number(b.dataset.minutes)*60;focusReset();document.querySelectorAll('[data-minutes]').forEach(x=>x.setAttribute('aria-pressed',x===b))});
const senses=[['Mira cinco detalles.','Busca una sombra, una forma o un cambio de color. Elige cinco cosas que normalmente pasarían desapercibidas.'],['Siente cuatro texturas.','Si te resulta cómodo, nota la ropa, el asiento o el aire en la piel. No hace falta tocar nada desconocido.'],['Escucha tres sonidos.','Distingue uno cercano y otro lejano. Si utilizas el mezclador, puedes detenerlo para escuchar tu entorno.'],['Percibe dos aromas.','Observa si hay algún olor familiar. Si no lo percibes, recuerda un aroma que te guste.'],['Reconoce un sabor.','Nota el sabor que queda en tu boca o recuerda uno agradable. No necesitas comer ni beber nada.']];let sense=-1,obDone=false;$('observe-next').onclick=()=>{sense++;if(sense>=senses.length){$('observe-title').textContent='Ya estás aquí.';$('observe-description').textContent='Elige un detalle de esta pausa para llevarlo contigo.';$('observe-count').textContent='Pausa completada';$('observe-next').disabled=true;$('observe-dots').textContent='● ● ● ● ●';if(!obDone){completed();obDone=true}return}const [title,description]=senses[sense];$('observe-title').textContent=title;$('observe-description').textContent=description;$('observe-count').textContent=`Paso ${sense+1} de 5`;$('observe-next').textContent=sense===4?'Terminar':'Siguiente';$('observe-dots').textContent=senses.map((_,i)=>i<=sense?'●':'○').join(' ')};$('observe-reset').onclick=()=>{sense=-1;obDone=false;$('observe-title').textContent='Haz sitio a lo cotidiano.';$('observe-description').textContent='Una pausa para prestar atención a lo que tienes cerca.';$('observe-count').textContent='5 sentidos · Sin cronómetro';$('observe-next').textContent='Comenzar';$('observe-next').disabled=false;$('observe-dots').textContent='○ ○ ○ ○ ○'};
const ideas=[['Mirada · 2 minutos','Sigue una sombra.','Elige una sombra cerca de tu ventana. Observa su borde, su forma y la superficie donde cae. Vuelve a mirarla más tarde: ¿qué ha cambiado?'],['Escucha · 1 minuto','Dibuja un mapa de sonidos.','Cierra los ojos si te resulta cómodo. Localiza tres sonidos y sitúalos mentalmente: cerca, lejos, a la izquierda o detrás. Después abre los ojos y comprueba qué has descubierto.'],['Creación · 5 minutos','Una foto, tres distancias.','Fotografía un elemento natural desde lejos, a media distancia y muy cerca. Compara qué cuenta cada imagen. No arranques ni alteres lo que encuentres.'],['Observación · 3 minutos','Encuentra una pequeña diferencia.','Busca dos hojas caídas. Compara sus nervios, bordes y tonos. Describe una diferencia concreta sin decidir cuál es más bonita.'],['Escucha · 2 minutos','Escucha entre los sonidos.','Elige un sonido repetido: pasos, agua o viento. Presta atención a los intervalos y a los cambios. ¿Es tan uniforme como parecía al principio?'],['Mirada · 2 minutos','Colecciona colores sin llevarte nada.','Encuentra cinco tonos distintos en un árbol, una planta o una vista desde la ventana. Ponles nombres propios. Puedes anotarlos o fotografiarlos.']];let ideaIndex=Number.isInteger(saved.ideaIndex)?saved.ideaIndex%ideas.length:0;if(!Array.isArray(saved.favorites))saved.favorites=[];function drawIdea(){const [cat,title,body]=ideas[ideaIndex];$('idea-category').textContent=cat;$('idea-title').textContent=title;$('idea-body').textContent=body;const yes=saved.favorites.includes(ideaIndex);$('idea-save').textContent=yes?'Quitar de guardadas':'Guardar propuesta';$('idea-saved').textContent=yes?'Guardada en este navegador.':'';drawFavorites()}function drawFavorites(){$('saved-count').textContent=`(${saved.favorites.length})`;$('saved-list').replaceChildren();for(const i of saved.favorites){if(!ideas[i])continue;const li=document.createElement('li'),b=document.createElement('button');li.textContent=ideas[i][1];b.textContent='Abrir';b.className='secondary';b.onclick=()=>{ideaIndex=i;drawIdea();$('idea-title').scrollIntoView({behavior:'smooth'})};li.append(b);$('saved-list').append(li)}if(!saved.favorites.length){const li=document.createElement('li');li.textContent='Todavía no has guardado propuestas.';$('saved-list').append(li)}}$('new-idea').onclick=()=>{ideaIndex=(ideaIndex+1)%ideas.length;saved.ideaIndex=ideaIndex;persist();drawIdea()};$('idea-save').onclick=()=>{saved.favorites=saved.favorites.includes(ideaIndex)?saved.favorites.filter(i=>i!==ideaIndex):[...saved.favorites,ideaIndex];persist();drawIdea()};drawIdea();$('clear-local').onclick=()=>{saved={favorites:[]};persist();intent.value='';counters();drawIdea();$('session-count').textContent='Datos locales borrados.'};document.querySelectorAll('[data-open-breath]').forEach(b=>b.onclick=e=>{e.preventDefault();tab('breath');$('explorar').scrollIntoView({behavior:'smooth'});$('breath-start').focus({preventScroll:true})});window.addEventListener('pagehide',()=>{stopSound();clearInterval(bt);clearInterval(ft)});
})();
